x solid $defaultColor;\n  padding: 5px;\n  border-radius: 10px;\n\n  & a {\n    &:hover {\n      color: $colorHover;\n    }\n  }\n}\n\n.publications__list-item-date-edit {\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  align-items: flex-start;\n  flex: 0 0 150px;\n}\n\n.article__status {\n  @include fonts($colorHover, 14px, 400);\n}\n\n.moderated {\n  @include fonts($asideExitColor, 14px, 400);\n}\n\n.publications__list-item-check {\n  display: flex;\n  gap: 5px;\n  @include fonts($defaultColor, 14px, 400);\n}\n\n:has(.article__status) .article__date {\n  align-self: flex-start;\n  flex: initial;\n}\n\n.article__date {\n  align-self: center;\n  flex: 0 0 150px;\n  display: block;\n  text-align: inherit;\n  @include fonts($defaultColor, 14px, 400);\n}\n\n.article__img {\n  display: block;\n  flex: 0 0 150px;\n  & img {\n    max-height: 90px;\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    object-position: center;\n  }\n}\n\n.article__about {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  justify-content: center;\n  & h3 {\n    & a {\n      @include fonts($mainColor, 16px, 400);\n    }\n  }\n\n  & div {\n    @include fonts($defaultColor, 14px, 400);\n  }\n\n  & input {\n    align-self: flex-start;\n  }\n}\n\n.article__edit {\n  align-self: start;\n  @include fonts($mainColor, 14px, 400);\n  &:hover {\n    color: $colorHover;\n  }\n}\n\n@media(max-width: 992px) {\n  .publications__list-item {\n    flex-direction: column;\n  }\n  \n  .article__edit {\n    order: 4;\n    align-self: initial;\n  }\n\n  .publications__list-item-date-edit{\n    flex: 0 0 100px;\n  }\n\n  .article__date {\n    flex: initial;\n    align-self: flex-start;\n    order: 3;\n  }\n\n  .article__about {\n    order: 2;\n  }\n\n  .article__img {\n    order: 1;\n    flex: initial;\n    & img {\n      max-height: 300px;\n    }\n  }\n}",".publications__list {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.publications__list-item {\n  display: flex;\n  gap: 15px;\n  border: 1px solid black;\n  padding: 5px;\n  border-radius: 10px;\n}\n.publications__list-item a:hover {\n  color: red;\n}\n\n.publications__list-item-date-edit {\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  align-items: flex-start;\n  flex: 0 0 150px;\n}\n\n.article__status {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: red;\n  font-size: 14px;\n}\n\n.moderated {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: rgb(0, 128, 0);\n  font-size: 14px;\n}\n\n.publications__list-item-check {\n  display: flex;\n  gap: 5px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n:has(.article__status) .article__date {\n  align-self: flex-start;\n  flex: initial;\n}\n\n.article__date {\n  align-self: center;\n  flex: 0 0 150px;\n  display: block;\n  text-align: inherit;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n.article__img {\n  display: block;\n  flex: 0 0 150px;\n}\n.article__img img {\n  max-height: 90px;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n\n.article__about {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  justify-content: center;\n}\n.article__about h3 a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 16px;\n}\n.article__about div {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.article__about input {\n  align-self: flex-start;\n}\n\n.article__edit {\n  align-self: start;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n}\n.article__edit:hover {\n  color: red;\n}\n\n@media (max-width: 992px) {\n  .publications__list-item {\n    flex-direction: column;\n  }\n  .article__edit {\n    order: 4;\n    align-self: initial;\n  }\n  .publications__list-item-date-edit {\n    flex: 0 0 100px;\n  }\n  .article__date {\n    flex: initial;\n    align-self: flex-start;\n    order: 3;\n  }\n  .article__about {\n    order: 2;\n  }\n  .article__img {\n    order: 1;\n    flex: initial;\n  }\n  .article__img img {\n    max-height: 300px;\n  }\n}\n.main__info-action {\n  margin-top: 10px;\n}\n.main__info-action p {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.main__info-action button {\n  padding: 7px;\n  border-radius: 5px;\n  background: none;\n  border: 1px solid black;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n.publications_count {\n  margin: 10px 0;\n}\n.publications_count p {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n.main__info-not-found {\n  text-align: center;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 24px;\n  margin-top: 40px;\n}","$mainColor: #3077a0;\n$defaultColor: black;\n$colorHover: red;\n$headerTopBorder: #bdd4e2;\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\n$gray: #D4D4D4;\n$vipBg: #ff6163;\n$activeItem: #FFFFCA;\n$userSearchBg: #CFE6FE;\n$asideLinksColor: #307792;\n$asideExitColor: rgb(0, 128, 0);","@mixin fonts($color,$size,$weight) {\n    font-family: 'Trebuchet MS', sans-serif;\n    font-weight: $weight;\n    font-style: normal;\n    color: $color;\n    font-size: $size;\n}","@import \"./variables\";\n@import \"./mixins\";\n@import \"./publicationsItem\";\n\n.main__info-action {\n  margin-top: 10px;\n\n  & p {\n    @include fonts($defaultColor, 14px, 400);\n  }\n\n  & button {\n    padding: 7px;\n    border-radius: 5px;\n    background: none;\n    border: 1px solid $defaultColor;\n    @include fonts($defaultColor, 14px, 400);\n  }\n}\n\n.publications_count {\n  margin: 10px 0;\n\n  & p {\n    @include fonts($defaultColor, 14px, 400);\n  }\n}\n\n.main__info-not-found {\n  text-align: center;\n  @include fonts($defaultColor, 24px, 400);\n  margin-top: 40px;\n}"]}defaultColor, 24px, 400);\n  margin-top: 40px;\n}"]}